<span class="line"></span>
<span class="line">    <span class="token comment">// 计算节点坐标</span></span>
<span class="line">    <span class="token keyword">function</span> <span class="token function">calcSubtreeSize</span><span class="token punctuation">(</span><span class="token parameter">node</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>node<span class="token punctuation">.</span>children <span class="token operator">||</span> node<span class="token punctuation">.</span>children<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        node<span class="token punctuation">.</span>_subtreeSize <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
